CREATE OR REPLACE FUNCTION public.srk_worker_respond_assignment(p_assignment_id uuid,p_accept boolean)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_worker_id uuid;
 v_accepted_count integer;
 v_requested_count integer;
 v_required_skill_level uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select bw.booking_id,bw.worker_id into v_booking_id,v_worker_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid();
 if not found then raise exception 'Offer not found or not yours'; end if;
 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found or v_booking.status='cancelled' then raise exception 'Booking is no longer available'; end if;
 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid()
 for update of bw;
 if not found or v_assignment.assignment_status<>'offered' then
  raise exception 'Offer not found or no longer pending';
 end if;
 if p_accept and v_assignment.offer_expires_at is not null
    and v_assignment.offer_expires_at<=clock_timestamp() then
  raise exception 'Offer has expired; wait for the next eligible assignment';
 end if;
 select * into v_worker from public.srk_worker_profiles where id=v_worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;

 if p_accept then
  if v_worker.verification_status<>'approved' or not v_worker.is_active then
   raise exception 'Worker is not currently approved and active';
  end if;
  v_required_skill_level:=coalesce(v_booking.higher_skill_consent_level_id,v_booking.requested_skill_level_id);
  if v_required_skill_level is not null and (
    v_assignment.skill_level_snapshot_id is distinct from v_required_skill_level
    or not exists(select 1 from public.srk_worker_skills ws
      where ws.worker_id=v_worker.id and ws.skill_id=v_booking.selected_skill_id
       and ws.skill_level_id=v_required_skill_level and ws.verification_status='approved')
  ) then
   raise exception 'Worker no longer matches the customer-approved qualification level';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_worker.id::text,0));
  if exists(select 1 from public.srk_worker_work_sessions s
            where s.worker_id=v_worker.id and s.session_status in ('running','paused'))
     or exists(select 1 from public.srk_booking_workers bw
               where bw.worker_id=v_worker.id and bw.assignment_status in ('working','paused')) then
   raise exception 'Finish or complete the active/paused booking before accepting another booking';
  end if;
  if exists(
   select 1 from public.srk_booking_workers bw
   where bw.worker_id=v_worker.id and bw.id<>v_assignment.id
    and bw.assignment_status in ('accepted','assigned')
    and not exists(select 1 from public.srk_worker_schedule_blocks sb
     where sb.booking_worker_id=bw.id and sb.block_status in ('reserved','confirmed','in_progress'))
  ) then
   raise exception 'Another accepted booking still needs a customer-confirmed schedule';
  end if;
  if exists(
   select 1 from public.srk_worker_schedule_blocks sb
   where sb.worker_id=v_worker.id and sb.block_status in ('reserved','confirmed','in_progress')
    and sb.starts_at<=clock_timestamp()+make_interval(hours=>coalesce(v_booking.requested_duration_hours,1))
    and sb.ends_at>clock_timestamp()
  ) then
   raise exception 'A confirmed worker schedule conflicts with this booking';
  end if;
  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;
  select count(*) into v_accepted_count from public.srk_booking_workers
  where booking_id=v_assignment.booking_id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
  if v_accepted_count>=v_requested_count then
   raise exception 'Requested number of this worker role has already been filled';
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
     accepted_at=case when p_accept then clock_timestamp() else null end,
     rejected_at=case when p_accept then null else clock_timestamp() end,
     offer_expires_at=null,updated_at=clock_timestamp()
 where id=p_assignment_id returning * into v_assignment;

 if p_accept then
  if v_assignment.worker_role='technician' then
   update public.service_bookings set status='confirmed'
   where id=v_assignment.booking_id and status='new';
  end if;
  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;
  select count(*) into v_accepted_count from public.srk_booking_workers
  where booking_id=v_assignment.booking_id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
  if v_accepted_count>=v_requested_count then
   update public.srk_booking_workers
   set assignment_status='rejected',rejected_at=clock_timestamp(),offer_expires_at=null,
       admin_note='Offer closed automatically: all requested positions filled by earlier acceptance.',
       updated_at=clock_timestamp()
   where booking_id=v_assignment.booking_id and worker_role=v_assignment.worker_role
     and assignment_status='offered' and id<>v_assignment.id;
  end if;
 end if;
 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_id=v_assignment.booking_id and queue_status not in ('fulfilled','cancelled');
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_process_booking_matching_queue()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public'
AS $function$
declare
 v_queue_candidate record;
 v_queue record;
 v_booking public.service_bookings%rowtype;
 v_timeout integer;
 v_max_attempts integer;
 v_default_timeout integer;
 v_default_max_attempts integer;
 v_tech_count integer;
 v_helper_count integer;
 v_tech_offered integer;
 v_helper_offered integer;
 v_candidate record;
 v_level uuid;
 v_rate_id uuid;
 v_rate numeric(10,2);
 v_role text;
 v_inserted integer:=0;
 v_offered boolean;
 v_rule public.srk_service_pricing_rules%rowtype;
begin
 select nullif(setting_value::text,'null')::integer into v_timeout
 from public.srk_system_settings where setting_key='offer_timeout_seconds';
 v_default_timeout:=v_timeout;
 select coalesce(nullif(setting_value::text,'null')::integer,10) into v_max_attempts
 from public.srk_system_settings where setting_key='max_matching_attempts';
 v_max_attempts:=coalesce(v_max_attempts,10);
 v_default_max_attempts:=v_max_attempts;

 if v_timeout is not null then
  update public.srk_booking_workers
  set assignment_status='rejected',rejected_at=clock_timestamp(),
      admin_note='Offer timed out',updated_at=clock_timestamp()
  where assignment_status='offered' and offer_expires_at is not null
    and offer_expires_at<=clock_timestamp();
 end if;

 for v_queue_candidate in
  select q.booking_id from public.srk_booking_matching_queue q
  where q.queue_status in ('pending','searching','waiting')
    and q.next_attempt_at<=clock_timestamp()
  order by q.created_at limit 25
 loop
  select * into v_booking from public.service_bookings
  where id=v_queue_candidate.booking_id for update skip locked;
  if not found then continue; end if;
  select * into v_queue from public.srk_booking_matching_queue q
  where q.booking_id=v_queue_candidate.booking_id
    and q.queue_status in ('pending','searching','waiting')
    and q.next_attempt_at<=clock_timestamp()
  for update skip locked;
  if not found then continue; end if;

  v_timeout:=coalesce((v_booking.operational_settings_snapshot->>'offer_timeout_seconds')::integer,v_default_timeout);
  v_max_attempts:=coalesce((v_booking.operational_settings_snapshot->>'max_matching_attempts')::integer,v_default_max_attempts);
  if v_booking.status='cancelled' then
   update public.srk_booking_matching_queue set queue_status='cancelled',updated_at=clock_timestamp()
   where booking_id=v_queue_candidate.booking_id;
   continue;
  end if;

  select count(*) into v_tech_count from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='technician'
   and assignment_status in ('accepted','assigned','working','paused','completed');
  select count(*) into v_helper_count from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='helper'
   and assignment_status in ('accepted','assigned','working','paused','completed');
  select count(*) into v_tech_offered from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='technician' and assignment_status='offered';
  select count(*) into v_helper_offered from public.srk_booking_workers
  where booking_id=v_booking.id and worker_role='helper' and assignment_status='offered';

  -- If a role is already filled, close every outstanding offer for that role.
  if v_tech_count>=v_booking.requested_technician_count then
   update public.srk_booking_workers
   set assignment_status='rejected',rejected_at=clock_timestamp(),offer_expires_at=null,
       admin_note='Offer closed automatically: all requested positions filled by earlier acceptance.',
       updated_at=clock_timestamp()
   where booking_id=v_booking.id and worker_role='technician' and assignment_status='offered';
   v_tech_offered:=0;
  end if;
  if v_helper_count>=v_booking.requested_helper_count then
   update public.srk_booking_workers
   set assignment_status='rejected',rejected_at=clock_timestamp(),offer_expires_at=null,
       admin_note='Offer closed automatically: all requested positions filled by earlier acceptance.',
       updated_at=clock_timestamp()
   where booking_id=v_booking.id and worker_role='helper' and assignment_status='offered';
   v_helper_offered:=0;
  end if;

  if v_tech_count>=1 then
   update public.service_bookings set status='confirmed' where id=v_booking.id and status='new';
  end if;
  if v_tech_count>=v_booking.requested_technician_count
     and v_helper_count>=v_booking.requested_helper_count then
   update public.srk_booking_workers set assignment_status='assigned',updated_at=clock_timestamp()
   where booking_id=v_booking.id and assignment_status='accepted';
   update public.srk_booking_matching_queue
   set queue_status='fulfilled',completed_at=coalesce(completed_at,clock_timestamp()),updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   update public.service_bookings set status='confirmed' where id=v_booking.id and status='new';
   continue;
  end if;

  v_role:=case when v_tech_count<v_booking.requested_technician_count then 'technician' else 'helper' end;
  if (v_role='technician' and v_tech_offered>0) or (v_role='helper' and v_helper_offered>0) then
   update public.srk_booking_matching_queue
   set queue_status='searching',next_attempt_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   continue;
  end if;
  if coalesce(v_queue.attempts,0)>=v_max_attempts then
   update public.srk_booking_matching_queue
   set queue_status='failed',
       last_error='Maximum matching attempts ('||v_max_attempts||') reached; required worker role remains unfilled.',
       next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
   where booking_id=v_booking.id;
   continue;
  end if;

  select * into v_rule from public.srk_service_pricing_rules where id=v_booking.pricing_rule_id;
  v_offered:=false;
  for v_candidate in
   select c.* from public.srk_find_eligible_workers(v_booking.id,v_role) c
   where not exists(select 1 from public.srk_booking_workers bw
    where bw.booking_id=v_booking.id and bw.worker_id=c.worker_id)
   order by c.distance_km
  loop
   select ws.skill_level_id into v_level from public.srk_worker_skills ws
   where ws.worker_id=v_candidate.worker_id and ws.skill_id=v_booking.selected_skill_id
    and ws.verification_status='approved' limit 1;
   v_rate_id:=null; v_rate:=null;
   if v_booking.pricing_unit_snapshot='motor_hp' then
    if v_rule.id is null or v_rule.pricing_unit<>'motor_hp'
       or not exists(select 1 from public.srk_service_pricing_hp_tiers t
        where t.pricing_rule_id=v_rule.id and t.motor_hp=v_booking.motor_hp) then
     continue;
    end if;
    v_rate:=null;
   elsif v_booking.pricing_unit_snapshot='per_item' then
    if v_rule.id is null or v_rule.pricing_unit<>'per_item' then continue; end if;
    if v_role='technician' then v_rate:=v_rule.technician_rate; else v_rate:=v_rule.helper_rate; end if;
    if v_role='technician' and (v_rate is null or v_rate<=0) then continue; end if;
   else
    if v_booking.pricing_rule_id is not null and v_rule.pricing_unit='hour' then
     if v_role='technician' then v_rate:=v_rule.technician_rate; else v_rate:=v_rule.helper_rate; end if;
     if v_rate is null then continue; end if;
    else
     select r.id,case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end
      into v_rate_id,v_rate
     from public.srk_service_rates r
     where r.category_id=v_booking.category_id and r.skill_level_id=v_level
      and (r.service_type_id is null or r.service_type_id=v_booking.service_type_id)
      and r.rate_status='approved' and r.effective_from<=clock_timestamp()
      and (r.effective_to is null or r.effective_to>clock_timestamp())
      and (case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end) is not null
     order by (r.service_type_id is not null) desc,r.effective_from desc limit 1;
     if v_rate is null then continue; end if;
    end if;
   end if;

   insert into public.srk_booking_workers(
    booking_id,worker_id,worker_role,assignment_status,rate_id,hourly_rate_snapshot,
    skill_level_snapshot_id,offer_expires_at,worker_custom_settings_snapshot
   ) values(
    v_booking.id,v_candidate.worker_id,v_role,'offered',v_rate_id,
    case when v_booking.pricing_unit_snapshot in ('per_item','motor_hp') then null else v_rate end,
    v_level,
    case when v_timeout is null then null else clock_timestamp()+make_interval(secs=>v_timeout) end,
    coalesce((select jsonb_object_agg(setting_key,setting_value)
     from public.srk_user_custom_settings
     where user_id=(select user_id from public.srk_worker_profiles where id=v_candidate.worker_id)
      and account_role=v_role),'{}'::jsonb)
   );
   v_inserted:=v_inserted+1;
   v_offered:=true;
  end loop;

  if v_offered then
   update public.srk_booking_matching_queue
   set queue_status='searching',attempts=attempts+1,last_attempt_at=clock_timestamp(),
       next_attempt_at=clock_timestamp()+make_interval(secs=>coalesce(v_timeout,600)),
       last_error=null,updated_at=clock_timestamp()
   where booking_id=v_booking.id;
  else
   update public.srk_booking_matching_queue
   set queue_status='waiting',attempts=attempts+1,last_attempt_at=clock_timestamp(),
       next_attempt_at=clock_timestamp()+interval '1 minute',
       last_error='No eligible online approved worker with an approved pricing rule/rate',
       updated_at=clock_timestamp()
   where booking_id=v_booking.id;
  end if;
 end loop;
 return v_inserted;
end
$function$;

alter table public.srk_service_types
 add constraint srk_service_types_no_active_winding_check
 check (
  not is_active or not (
   service_code ~* 'wind|rewind'
   or service_name ~* 'wind|rewind|वाइंड|वाइन्ड'
  )
 );

CREATE OR REPLACE FUNCTION public.srk_admin_add_service_type(
 p_category_id uuid,p_service_code text,p_service_name text,p_sort_order integer,p_reason text
) RETURNS public.srk_service_types
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare v public.srk_service_types%rowtype;
begin
 if auth.uid() is null or not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Catalog management permission required';
 end if;
 if length(coalesce(p_reason,''))<10 then
  raise exception 'Reason must be at least 10 characters';
 end if;
 if p_service_code !~ '^[a-z][a-z0-9_]{1,59}$' or length(btrim(p_service_name)) not between 2 and 120 then
  raise exception 'Invalid service code or name';
 end if;
 if p_service_code ~* 'wind|rewind'
    or p_service_name ~* 'wind|rewind|वाइंड|वाइन्ड' then
  raise exception 'Motor Winding is permanently outside the SRK ELECTRONIC service catalog';
 end if;
 insert into public.srk_service_types(category_id,service_code,service_name,sort_order,is_active,admin_note)
 values(p_category_id,p_service_code,btrim(p_service_name),coalesce(p_sort_order,0),true,btrim(p_reason))
 returning * into v;
 return v;
end
$function$;

REVOKE ALL ON FUNCTION public.srk_admin_add_service_type(uuid,text,text,integer)
FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.srk_admin_publish_service_rate(
 p_category_id uuid,p_service_type_id uuid,p_skill_level_id uuid,
 p_technician_hourly_rate numeric,p_helper_hourly_rate numeric,p_reason text
) RETURNS public.srk_service_rates
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_rate public.srk_service_rates%rowtype;
 v_changed_at timestamptz:=clock_timestamp();
begin
 if auth.uid() is null or not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Catalog management permission required';
 end if;
 if length(btrim(coalesce(p_reason,'')))<10 then
  raise exception 'Rate change reason must be at least 10 characters';
 end if;
 if p_technician_hourly_rate is null or p_technician_hourly_rate<0
    or p_helper_hourly_rate is null or p_helper_hourly_rate<0 then
  raise exception 'Both hourly rates must be non-negative';
 end if;
 if not exists(select 1 from public.srk_service_categories c
  where c.id=p_category_id and c.is_active) then
  raise exception 'Active service category is required';
 end if;
 if not exists(select 1 from public.srk_skill_levels l
  where l.id=p_skill_level_id and l.category_id=p_category_id and l.is_active) then
  raise exception 'Active skill level/category mismatch';
 end if;
 if p_service_type_id is not null and not exists(
  select 1 from public.srk_service_types s
  where s.id=p_service_type_id and s.category_id=p_category_id and s.is_active
 ) then
  raise exception 'Active service type/category mismatch';
 end if;

 perform pg_advisory_xact_lock(hashtextextended(
  p_category_id::text||':'||coalesce(p_service_type_id::text,'<NULL>')||':'||p_skill_level_id::text,0));

 update public.srk_service_rates
 set effective_to=v_changed_at,rate_status='retired',
     change_reason=concat_ws('; ',nullif(change_reason,''),'Superseded: '||btrim(p_reason))
 where category_id=p_category_id and service_type_id is not distinct from p_service_type_id
  and skill_level_id=p_skill_level_id and rate_status='approved' and effective_to is null;

 insert into public.srk_service_rates(
  category_id,service_type_id,skill_level_id,technician_hourly_rate,helper_hourly_rate,
  rate_status,effective_from,created_by,change_reason
 ) values(
  p_category_id,p_service_type_id,p_skill_level_id,p_technician_hourly_rate,p_helper_hourly_rate,
  'approved',v_changed_at,auth.uid(),btrim(p_reason)
 ) returning * into v_rate;
 return v_rate;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_update_service_rate(
 p_rate_id uuid,p_technician_hourly_rate numeric,p_helper_hourly_rate numeric,p_change_reason text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_old public.srk_service_rates%rowtype;
 v_new_id uuid;
 v_changed_at timestamptz:=clock_timestamp();
begin
 if auth.uid() is null or not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Catalog management permission required';
 end if;
 if p_rate_id is null then raise exception 'Rate ID is required'; end if;
 if p_technician_hourly_rate is null or p_technician_hourly_rate<=0 then
  raise exception 'Technician hourly rate must be positive';
 end if;
 if p_helper_hourly_rate is not null and p_helper_hourly_rate<=0 then
  raise exception 'Helper hourly rate must be positive when supplied';
 end if;
 if length(btrim(coalesce(p_change_reason,'')))<10 then
  raise exception 'Rate change reason must be at least 10 characters';
 end if;

 select * into v_old from public.srk_service_rates where id=p_rate_id;
 if not found then raise exception 'Rate not found'; end if;
 perform pg_advisory_xact_lock(hashtextextended(
  v_old.category_id::text||':'||coalesce(v_old.service_type_id::text,'<NULL>')||':'||v_old.skill_level_id::text,0));

 select * into v_old from public.srk_service_rates
 where id=p_rate_id and effective_to is null and rate_status='approved' for update;
 if not found then
  raise exception 'Current approved legacy rate not found; drafts and retired rates cannot be changed here';
 end if;
 if not exists(select 1 from public.srk_service_categories c
  where c.id=v_old.category_id and c.is_active)
  or not exists(select 1 from public.srk_skill_levels l
   where l.id=v_old.skill_level_id and l.category_id=v_old.category_id and l.is_active)
  or (v_old.service_type_id is not null and not exists(
   select 1 from public.srk_service_types s
   where s.id=v_old.service_type_id and s.category_id=v_old.category_id and s.is_active
  )) then
  raise exception 'Only rates for active catalog items can be changed';
 end if;
 if exists(
  select 1 from public.srk_service_pricing_rules r
  where r.category_id=v_old.category_id and r.service_type_id=v_old.service_type_id
   and r.effective_from<=v_changed_at and (r.effective_to is null or r.effective_to>v_changed_at)
 ) then
  raise exception 'This service uses the versioned pricing rules. Update it through srk_admin_version_service_pricing_rule instead of the legacy hourly-rate manager';
 end if;

 update public.srk_service_rates
 set effective_to=v_changed_at,
     change_reason=concat_ws('; ',nullif(change_reason,''),'Superseded by admin rate adjustment')
 where id=v_old.id;

 insert into public.srk_service_rates(
  category_id,service_type_id,skill_level_id,technician_hourly_rate,
  helper_hourly_rate,rate_status,effective_from,created_by,change_reason
 ) values(
  v_old.category_id,v_old.service_type_id,v_old.skill_level_id,
  p_technician_hourly_rate,p_helper_hourly_rate,'approved',v_changed_at,
  auth.uid(),btrim(p_change_reason)
 ) returning id into v_new_id;

 return jsonb_build_object(
  'success',true,'previous_rate_id',v_old.id,'new_rate_id',v_new_id,
  'technician_hourly_rate',p_technician_hourly_rate,
  'helper_hourly_rate',p_helper_hourly_rate,'effective_from',v_changed_at
 );
end
$function$;

REVOKE ALL ON FUNCTION public.srk_admin_publish_service_rate(uuid,uuid,uuid,numeric,numeric)
FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.srk_admin_publish_service_rate(
 p_category_id uuid,p_service_type_id uuid,p_skill_level_id uuid,
 p_technician_hourly_rate numeric,p_helper_hourly_rate numeric,p_reason text
) RETURNS public.srk_service_rates
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_rate public.srk_service_rates%rowtype;
 v_changed_at timestamptz:=clock_timestamp();
begin
 if auth.uid() is null or not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Catalog management permission required';
 end if;
 if length(btrim(coalesce(p_reason,'')))<10 then raise exception 'Rate change reason must be at least 10 characters'; end if;
 if p_technician_hourly_rate is null or p_technician_hourly_rate<0
    or p_helper_hourly_rate is null or p_helper_hourly_rate<0 then
  raise exception 'Both hourly rates must be non-negative';
 end if;
 if not exists(select 1 from public.srk_service_categories c where c.id=p_category_id and c.is_active) then
  raise exception 'Active service category is required';
 end if;
 if not exists(select 1 from public.srk_skill_levels l
  where l.id=p_skill_level_id and l.category_id=p_category_id and l.is_active) then
  raise exception 'Active skill level/category mismatch';
 end if;
 if p_service_type_id is not null and not exists(
  select 1 from public.srk_service_types s
  where s.id=p_service_type_id and s.category_id=p_category_id and s.is_active
 ) then
  raise exception 'Active service type/category mismatch';
 end if;
 if exists(select 1 from public.srk_service_pricing_rules r
  where r.category_id=p_category_id and r.service_type_id is not distinct from p_service_type_id
   and r.effective_from<=v_changed_at and (r.effective_to is null or r.effective_to>v_changed_at)) then
  raise exception 'This catalog item uses versioned pricing rules; use the versioned pricing manager';
 end if;

 perform pg_advisory_xact_lock(hashtextextended(
  p_category_id::text||':'||coalesce(p_service_type_id::text,'<NULL>')||':'||p_skill_level_id::text,0));
 update public.srk_service_rates
 set effective_to=v_changed_at,rate_status='retired',
     change_reason=concat_ws('; ',nullif(change_reason,''),'Superseded: '||btrim(p_reason))
 where category_id=p_category_id and service_type_id is not distinct from p_service_type_id
  and skill_level_id=p_skill_level_id and rate_status='approved' and effective_to is null;
 insert into public.srk_service_rates(
  category_id,service_type_id,skill_level_id,technician_hourly_rate,helper_hourly_rate,
  rate_status,effective_from,created_by,change_reason
 ) values(
  p_category_id,p_service_type_id,p_skill_level_id,p_technician_hourly_rate,p_helper_hourly_rate,
  'approved',v_changed_at,auth.uid(),btrim(p_reason)
 ) returning * into v_rate;
 return v_rate;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_version_service_pricing_rule(
 p_pricing_rule_id uuid,p_pricing_unit text,p_technician_rate numeric,p_helper_rate numeric,
 p_base_hp numeric,p_base_hp_price numeric,p_hp_step_amount numeric,p_timer_enabled boolean,
 p_materials_charged_separately boolean,p_winding_charged_separately boolean,
 p_pricing_note text,p_hp_tiers jsonb,p_change_reason text
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_old public.srk_service_pricing_rules%rowtype;
 v_new_id uuid;
 v_now timestamptz:=clock_timestamp();
 v_tier_count integer:=0;
 v_bad_count integer:=0;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Permission denied: catalog.manage required';
 end if;
 if p_pricing_rule_id is null then raise exception 'Pricing rule ID is required'; end if;
 if p_pricing_unit not in ('hour','per_item','motor_hp') then raise exception 'Invalid pricing unit'; end if;
 if p_timer_enabled is null or p_materials_charged_separately is null or p_winding_charged_separately is null then
  raise exception 'Pricing flags are required';
 end if;
 if p_materials_charged_separately is true then
  raise exception 'Material billing is disabled by the approved SRK ELECTRONIC policy';
 end if;
 if p_helper_rate is not null and p_helper_rate<0 then
  raise exception 'Helper rate cannot be negative';
 end if;
 if p_change_reason is null or length(btrim(p_change_reason))<10 then
  raise exception 'Change reason must contain at least 10 non-space characters';
 end if;
 if p_hp_tiers is null or jsonb_typeof(p_hp_tiers)<>'array' then
  raise exception 'HP tiers must be supplied as a JSON array (use [] when not applicable)';
 end if;
 if p_pricing_unit='hour' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not true
     or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
     or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Hourly pricing requires positive technician rate, timer enabled, and no HP fields/tiers';
  end if;
 elsif p_pricing_unit='per_item' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not false
     or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
     or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Per-item pricing requires positive item rate, timer disabled, and no HP fields/tiers';
  end if;
 else
  if p_timer_enabled is not false or p_base_hp is null or p_base_hp<0.5
     or p_base_hp_price is null or p_base_hp_price<=0 or p_hp_step_amount is null or p_hp_step_amount<=0
     or p_technician_rate is not null or p_helper_rate is not null
     or jsonb_array_length(p_hp_tiers)=0 then
   raise exception 'Motor HP pricing requires timer disabled, positive HP base values and HP tiers';
  end if;
  if exists(select 1 from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric)
   where motor_hp is null or motor_hp<0.5 or fixed_price is null or fixed_price<=0) then
   raise exception 'Every HP tier requires motor_hp >= 0.5 and positive fixed_price';
  end if;
  select count(*) into v_tier_count from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
  select count(*) into v_bad_count from (
   select x.motor_hp from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric)
   group by x.motor_hp having count(*)>1
  ) d;
  if v_tier_count=0 or v_bad_count>0 then raise exception 'HP tiers must be non-empty and have unique HP values'; end if;
 end if;

 perform pg_advisory_xact_lock(hashtextextended(p_pricing_rule_id::text,0));
 select * into v_old from public.srk_service_pricing_rules
 where id=p_pricing_rule_id for update;
 if not found then raise exception 'Pricing rule not found'; end if;
 if v_old.effective_to is not null then raise exception 'Only the current pricing rule version can be changed'; end if;
 if v_now<=v_old.effective_from then raise exception 'Pricing rule effective time conflict'; end if;
 if not exists(select 1 from public.srk_service_categories c where c.id=v_old.category_id and c.is_active)
  or not exists(select 1 from public.srk_service_types s
   where s.id=v_old.service_type_id and s.category_id=v_old.category_id and s.is_active) then
  raise exception 'Only active catalog items can receive a new pricing version';
 end if;

 update public.srk_service_pricing_rules set effective_to=v_now
 where id=v_old.id and effective_to is null;
 insert into public.srk_service_pricing_rules(
  category_id,service_type_id,pricing_unit,technician_rate,helper_rate,
  base_hp,base_hp_price,hp_step_amount,timer_enabled,
  materials_charged_separately,winding_charged_separately,pricing_note,
  effective_from,effective_to,created_by,change_reason
 ) values(
  v_old.category_id,v_old.service_type_id,p_pricing_unit,p_technician_rate,p_helper_rate,
  p_base_hp,p_base_hp_price,p_hp_step_amount,p_timer_enabled,
  false,p_winding_charged_separately,nullif(btrim(p_pricing_note),''),
  v_now,null,auth.uid(),btrim(p_change_reason)
 ) returning id into v_new_id;
 if p_pricing_unit='motor_hp' then
  insert into public.srk_service_pricing_hp_tiers(pricing_rule_id,motor_hp,fixed_price,created_by)
  select v_new_id,x.motor_hp,x.fixed_price,auth.uid()
  from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
 end if;
 return v_new_id;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_create_booking(
 p_category_id uuid,p_service_type_id uuid,p_skill_id uuid,
 p_technician_count integer,p_helper_count integer,p_duration_hours integer,
 p_state text,p_district text,p_pincode text,p_address text,
 p_booking_latitude double precision,p_booking_longitude double precision,
 p_current_gps_latitude double precision,p_current_gps_longitude double precision,
 p_motor_hp numeric,p_skill_level_id uuid,p_unit_count integer
) RETURNS public.service_bookings
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_customer public.srk_customer_profiles%rowtype;
 v_service public.srk_service_types%rowtype;
 v_booking public.service_bookings%rowtype;
 v_rule public.srk_service_pricing_rules%rowtype;
 v_unit text;
 v_max_tech integer;
 v_max_helper integer;
 v_min_duration integer;
 v_max_duration integer;
 v_location_source text;
 v_requested_level public.srk_skill_levels%rowtype;
 v_settings_snapshot jsonb;
 v_pending_fee_amount numeric(12,2):=0;
 v_user_settings_snapshot jsonb:='{}'::jsonb;
begin
 if auth.uid() is null then raise exception 'OTP login required' using errcode='42501'; end if;
 select * into v_customer from public.srk_customer_profiles where user_id=auth.uid();
 if not found then raise exception 'Complete customer profile before booking'; end if;
 if v_customer.account_status<>'active' then raise exception 'Customer account is restricted from new bookings'; end if;

 select coalesce((select (setting_value #>> '{}')::integer from public.srk_system_settings where setting_key='max_technicians_per_booking'),10),
        coalesce((select (setting_value #>> '{}')::integer from public.srk_system_settings where setting_key='max_helpers_per_booking'),10),
        coalesce((select (setting_value #>> '{}')::integer from public.srk_system_settings where setting_key='minimum_booking_duration_hours'),1),
        coalesce((select (setting_value #>> '{}')::integer from public.srk_system_settings where setting_key='maximum_booking_duration_hours'),1440)
 into v_max_tech,v_max_helper,v_min_duration,v_max_duration;
 select coalesce(jsonb_object_agg(setting_key,setting_value),'{}'::jsonb) into v_settings_snapshot
 from public.srk_system_settings
 where setting_key in ('max_technicians_per_booking','max_helpers_per_booking','minimum_booking_duration_hours','maximum_booking_duration_hours',
 'normal_daily_billable_hours','overtime_multiplier','initial_matching_radius_km','matching_radius_expansion_step_km','maximum_matching_radius_km',
 'offer_timeout_seconds','max_matching_attempts','no_show_wait_minutes','cancellation_free_window_minutes','cancellation_technician_on_way_fee',
 'cancellation_technician_arrived_fee','lunch_pause_minimum_minutes','other_pause_minimum_minutes','pause_auto_resume_distance_meters');
 select coalesce(jsonb_object_agg(setting_key,setting_value),'{}'::jsonb)
 into v_user_settings_snapshot
 from public.srk_user_custom_settings
 where user_id=auth.uid() and account_role='customer';

 if p_technician_count is null or p_helper_count is null
    or p_technician_count not between 1 and greatest(1,least(v_max_tech,20))
    or p_helper_count not between 0 and greatest(0,least(v_max_helper,20)) then
  raise exception 'Requested Technician/Helper count exceeds the configured booking limit';
 end if;
 if p_duration_hours is null or p_duration_hours not between greatest(1,v_min_duration) and least(1440,v_max_duration) then
  raise exception 'Duration must be within the configured booking duration limits';
 end if;
 if p_pincode !~ '^[0-9]{6}$' or nullif(btrim(p_state),'') is null
    or nullif(btrim(p_district),'') is null or nullif(btrim(p_address),'') is null then
  raise exception 'Complete valid booking address required';
 end if;
 if (p_booking_latitude is null)<>(p_booking_longitude is null) then
  raise exception 'Booking GPS coordinates must be supplied together';
 end if;
 if p_booking_latitude is not null and
    (p_booking_latitude not between -90 and 90 or p_booking_longitude not between -180 and 180) then
  raise exception 'Invalid booking GPS coordinates';
 end if;
 v_location_source:=case when p_booking_latitude is null then 'manual' else 'gps' end;
 if (p_current_gps_latitude is null)<>(p_current_gps_longitude is null) then
  raise exception 'Current GPS coordinates must be supplied together';
 end if;
 if p_current_gps_latitude is not null and
    (p_current_gps_latitude not between -90 and 90 or p_current_gps_longitude not between -180 and 180) then
  raise exception 'Invalid current GPS coordinates';
 end if;

 select * into v_service from public.srk_service_types
 where id=p_service_type_id and category_id=p_category_id and is_active;
 if not found then raise exception 'Service does not belong to active category'; end if;
 if not exists(select 1 from public.srk_service_skills
  where id=p_skill_id and service_type_id=p_service_type_id and is_active) then
  raise exception 'Work/skill does not belong to selected service';
 end if;
 if p_skill_level_id is not null then
  select * into v_requested_level from public.srk_skill_levels
  where id=p_skill_level_id and category_id=p_category_id and is_active;
  if not found then raise exception 'Selected qualification level is not active for this category'; end if;
 else
  select * into v_requested_level from public.srk_skill_levels
  where category_id=p_category_id and is_active order by sort_order limit 1;
  p_skill_level_id:=v_requested_level.id;
 end if;

 select * into v_rule from public.srk_service_pricing_rules
 where category_id=p_category_id and service_type_id=p_service_type_id
  and effective_from<=clock_timestamp() and (effective_to is null or effective_to>clock_timestamp())
 order by effective_from desc limit 1;
 if found then
  v_unit:=v_rule.pricing_unit;
  if v_unit='motor_hp' then
   if p_motor_hp is null or p_motor_hp<0.5 or p_motor_hp*2<>trunc(p_motor_hp*2) then
    raise exception 'Motor HP must be selected in 0.5 HP increments, starting at 0.5 HP';
   end if;
   if not exists(select 1 from public.srk_service_pricing_hp_tiers t
    where t.pricing_rule_id=v_rule.id and t.motor_hp=p_motor_hp) then
    raise exception 'No approved fixed price exists for this motor HP';
   end if;
  elsif p_motor_hp is not null then
   raise exception 'Motor HP must only be supplied for Motor/Pump HP-priced services';
  end if;
  if v_unit='per_item' and (v_rule.technician_rate is null or v_rule.technician_rate<=0) then
   raise exception 'Approved fixed per-item Technician price is missing';
  end if;
 else
  v_unit:='hour';
  if p_motor_hp is not null then raise exception 'Motor HP is not applicable to this service'; end if;
 end if;

 if p_unit_count is null or p_unit_count<1 then
  raise exception 'Unit count must be at least one';
 end if;
 if v_unit<>'per_item' and p_unit_count<>1 then
  raise exception 'Unit count is only selectable for per-item services';
 end if;

 insert into public.service_bookings(
  customer_name,phone,state,district,pincode,address,service_type,payment_method,status,
  commission_rate,materials_amount,customer_user_id,customer_id,category_id,service_type_id,selected_skill_id,
  requested_technician_count,requested_helper_count,requested_duration_hours,booking_latitude,booking_longitude,requested_skill_level_id,
  location_lat,location_lng,booking_address_confirmed_at,booking_location_source,
  pricing_unit_snapshot,pricing_quantity,pricing_rule_id,motor_hp,operational_settings_snapshot,user_custom_settings_snapshot
 ) values(
  v_customer.full_name,v_customer.phone,btrim(p_state),btrim(p_district),p_pincode,btrim(p_address),v_service.service_name,
  'Unselected','new',15.00,0,auth.uid(),v_customer.id,p_category_id,p_service_type_id,p_skill_id,
  p_technician_count,p_helper_count,p_duration_hours,p_booking_latitude,p_booking_longitude,p_skill_level_id,
  p_current_gps_latitude,p_current_gps_longitude,clock_timestamp(),v_location_source,
  v_unit,case when v_unit='per_item' then p_unit_count when v_unit='motor_hp' then 1 else null end,
  case when v_rule.id is not null then v_rule.id else null end,p_motor_hp,v_settings_snapshot,v_user_settings_snapshot
 ) returning * into v_booking;

 insert into public.srk_booking_matching_queue(booking_id,queue_status) values(v_booking.id,'pending');
 if v_booking.requested_skill_level_id is not null then
  insert into public.srk_booking_skill_level_events(booking_id,actor_user_id,event_type,to_skill_level_id,reason)
  values(v_booking.id,auth.uid(),'requested_level_selected',v_booking.requested_skill_level_id,
   'Qualification level selected/defaulted at booking creation');
 end if;
 update public.srk_booking_cancellation_fees
 set status='added_to_next_booking',next_booking_id=v_booking.id,added_to_next_booking_at=clock_timestamp()
 where customer_user_id=auth.uid() and status='pending';
 select coalesce(sum(fee_amount),0) into v_pending_fee_amount
 from public.srk_booking_cancellation_fees
 where next_booking_id=v_booking.id and status='added_to_next_booking';
 if v_pending_fee_amount>0 then
  update public.service_bookings set pending_cancellation_fee_amount=v_pending_fee_amount
  where id=v_booking.id returning * into v_booking;
 end if;
 return v_booking;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_create_booking(
 p_category_id uuid,p_service_type_id uuid,p_skill_id uuid,
 p_technician_count integer,p_helper_count integer,p_duration_hours integer,
 p_state text,p_district text,p_pincode text,p_address text,
 p_booking_latitude double precision,p_booking_longitude double precision,
 p_current_gps_latitude double precision,p_current_gps_longitude double precision,
 p_motor_hp numeric,p_skill_level_id uuid
) RETURNS public.service_bookings
LANGUAGE sql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
 select public.srk_customer_create_booking(
  p_category_id,p_service_type_id,p_skill_id,p_technician_count,p_helper_count,p_duration_hours,
  p_state,p_district,p_pincode,p_address,p_booking_latitude,p_booking_longitude,
  p_current_gps_latitude,p_current_gps_longitude,p_motor_hp,p_skill_level_id,1
 );
$function$;

REVOKE ALL ON FUNCTION public.srk_customer_create_booking(uuid,uuid,uuid,integer,integer,integer,text,text,text,text,double precision,double precision,double precision,double precision,numeric,uuid,integer)
FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.srk_customer_create_booking(uuid,uuid,uuid,integer,integer,integer,text,text,text,text,double precision,double precision,double precision,double precision,numeric,uuid,integer)
TO authenticated;

CREATE OR REPLACE FUNCTION public.srk_admin_prepare_booking_refund(p_request_id uuid)
RETURNS TABLE(refund_record_id uuid, booking_id uuid, payment_id text, amount_paise bigint, idempotency_key text, status text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
 v_request public.srk_booking_refund_requests%rowtype;
 v_booking public.service_bookings%rowtype;
 v_order public.srk_razorpay_payment_orders%rowtype;
 v_bill public.srk_booking_final_bills%rowtype;
 v_refund public.srk_razorpay_refunds%rowtype;
 v_payout public.srk_electrician_payouts%rowtype;
 v_amount numeric(12,2);
 v_has_legacy_payout boolean := false;
begin
 if auth.uid() is null or not public.is_srk_admin() then
  raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';
 end if;
 select * into v_request from public.srk_booking_refund_requests
 where id=p_request_id for update;
 if not found then raise exception 'REFUND_REQUEST_NOT_FOUND'; end if;
 if v_request.status not in ('approved','processing','unknown') then
  raise exception 'REFUND_REQUEST_MUST_BE_APPROVED_FIRST' using errcode='55000';
 end if;
 select * into v_booking from public.service_bookings where id=v_request.booking_id;
 if not found or v_booking.razorpay_order_id is null then
  raise exception 'VERIFIED_RAZORPAY_PAYMENT_ORDER_REQUIRED' using errcode='55000';
 end if;
 select po.* into v_order from public.srk_razorpay_payment_orders po
 where po.booking_id=v_booking.id and po.razorpay_order_id=v_booking.razorpay_order_id for update;
 if not found or v_order.status<>'paid' or v_order.currency<>'INR' then
  raise exception 'PAID_RAZORPAY_ORDER_SNAPSHOT_REQUIRED' using errcode='55000';
 end if;
 select * into v_booking from public.service_bookings where id=v_request.booking_id for update;
 if not found or v_booking.razorpay_order_id is distinct from v_order.razorpay_order_id then
  raise exception 'BOOKING_PAYMENT_ORDER_CHANGED';
 end if;
 if v_booking.payment_status<>'paid' or v_booking.payment_verified_at is null
  or v_booking.razorpay_payment_id is null
  or v_booking.razorpay_payment_id !~ '^pay_[A-Za-z0-9]+$'
  or coalesce(v_booking.amount_paid,0)<=0 then
  raise exception 'VERIFIED_RAZORPAY_PAYMENT_REQUIRED' using errcode='55000';
 end if;
 select * into v_bill from public.srk_booking_final_bills
 where id=v_order.final_bill_id and booking_id=v_booking.id for update;
 if not found or v_order.final_bill_revision is null
  or v_bill.revision_no is distinct from v_order.final_bill_revision
  or v_bill.status not in ('issued','approved') or v_bill.total_amount is null
  or round(v_bill.total_amount*100)::bigint<>v_order.amount_paise
  or round(v_booking.amount_paid*100)::bigint<>v_order.amount_paise then
  raise exception 'PAID_AMOUNT_DOES_NOT_MATCH_FINAL_BILL_SNAPSHOT' using errcode='55000';
 end if;
 v_amount:=round(v_booking.amount_paid,2);
 if round(v_request.amount,2)<>v_amount then
  raise exception 'REFUND_AMOUNT_MUST_EQUAL_FULL_PAID_BOOKING_AMOUNT' using errcode='55000';
 end if;
 if exists(
  select 1 from public.srk_worker_payout_earning_allocations a
  join public.srk_worker_payout_requests p on p.id=a.payout_request_id
  where a.booking_id=v_booking.id and p.status='paid'
 ) or exists(
  select 1 from public.srk_worker_earnings e
  join public.srk_worker_payout_requests p on p.worker_id=e.worker_id and p.status='paid'
  where e.booking_id=v_booking.id and not exists(
   select 1 from public.srk_worker_payout_earning_allocations a
   where a.payout_request_id=p.id
  )
 ) then raise exception 'BOOKING_WORKER_PAYOUT_ALREADY_PAID_RECONCILIATION_REQUIRED'; end if;
 select * into v_refund from public.srk_razorpay_refunds rr
 where rr.booking_id=v_booking.id for update;
 if found then
  if v_refund.status='failed' then raise exception 'PREVIOUS_REFUND_FAILED_RECONCILE_FIRST'; end if;
  if v_refund.payment_id is distinct from v_booking.razorpay_payment_id
   or v_refund.amount_paise<>round(v_amount*100)::bigint then
   raise exception 'EXISTING_REFUND_DOES_NOT_MATCH_PAID_FINAL_BILL';
  end if;
  update public.srk_booking_refund_requests
  set status=case when v_refund.status='processed' then 'processed' else 'processing' end,
   refund_record_id=v_refund.id,updated_at=clock_timestamp(),
   processed_at=case when v_refund.status='processed' then coalesce(v_refund.processed_at,clock_timestamp()) else null end
  where id=v_request.id;
  return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,
   v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
  return;
 end if;
 select * into v_payout from public.srk_electrician_payouts
 where booking_id=v_booking.id for update;
 if found then
  v_has_legacy_payout:=true;
  if v_payout.payout_status='paid' then raise exception 'LEGACY_WORKER_PAYOUT_ALREADY_PAID_RECONCILIATION_REQUIRED'; end if;
  if v_payout.payout_status not in ('pending','blocked') then raise exception 'LEGACY_WORKER_PAYOUT_STATE_REQUIRES_RECONCILIATION'; end if;
  update public.srk_electrician_payouts
  set payout_status='blocked',payout_note='Customer refund in progress',updated_at=clock_timestamp()
  where id=v_payout.id;
 end if;
 insert into public.srk_razorpay_refunds
  (booking_id,payment_id,amount,amount_paise,idempotency_key,status,reason,admin_user_id,previous_payout_note)
 values
  (v_booking.id,v_booking.razorpay_payment_id,v_amount,round(v_amount*100)::bigint,
   replace(gen_random_uuid()::text,'-',''),'requested',
   left('Customer refund request: '||v_request.reason,250),auth.uid(),
   case when v_has_legacy_payout then v_payout.payout_note else null end)
 returning * into v_refund;
 update public.srk_booking_refund_requests
 set status='processing',refund_record_id=v_refund.id,decided_by=auth.uid(),updated_at=clock_timestamp()
 where id=v_request.id;
 return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,
  v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_prepare_booking_refund(p_request_id uuid)
RETURNS TABLE(refund_record_id uuid, booking_id uuid, payment_id text, amount_paise bigint, idempotency_key text, status text)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
 v_request public.srk_booking_refund_requests%rowtype;
 v_booking public.service_bookings%rowtype;
 v_order public.srk_razorpay_payment_orders%rowtype;
 v_bill public.srk_booking_final_bills%rowtype;
 v_refund public.srk_razorpay_refunds%rowtype;
 v_payout public.srk_electrician_payouts%rowtype;
 v_amount numeric(12,2);
 v_has_legacy_payout boolean := false;
begin
 if auth.uid() is null or not public.is_srk_admin() then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501'; end if;
 select * into v_request from public.srk_booking_refund_requests where id=p_request_id for update;
 if not found then raise exception 'REFUND_REQUEST_NOT_FOUND'; end if;
 if v_request.status not in ('approved','processing','unknown') then raise exception 'REFUND_REQUEST_MUST_BE_APPROVED_FIRST' using errcode='55000'; end if;
 select * into v_booking from public.service_bookings where id=v_request.booking_id;
 if not found or v_booking.razorpay_order_id is null then raise exception 'VERIFIED_RAZORPAY_PAYMENT_ORDER_REQUIRED' using errcode='55000'; end if;
 select po.* into v_order from public.srk_razorpay_payment_orders po
 where po.booking_id=v_booking.id and po.razorpay_order_id=v_booking.razorpay_order_id for update;
 if not found or v_order.status<>'paid' or v_order.currency<>'INR' then raise exception 'PAID_RAZORPAY_ORDER_SNAPSHOT_REQUIRED' using errcode='55000'; end if;
 select * into v_booking from public.service_bookings where id=v_request.booking_id for update;
 if not found or v_booking.razorpay_order_id is distinct from v_order.razorpay_order_id then raise exception 'BOOKING_PAYMENT_ORDER_CHANGED'; end if;
 if v_booking.payment_status<>'paid' or v_booking.payment_verified_at is null
  or v_booking.razorpay_payment_id is null or v_booking.razorpay_payment_id !~ '^pay_[A-Za-z0-9]+$'
  or coalesce(v_booking.amount_paid,0)<=0 then raise exception 'VERIFIED_RAZORPAY_PAYMENT_REQUIRED' using errcode='55000'; end if;
 select fb.* into v_bill from public.srk_booking_final_bills fb
 where fb.id=v_order.final_bill_id and fb.booking_id=v_booking.id for update;
 if not found or v_order.final_bill_revision is null or v_bill.revision_no is distinct from v_order.final_bill_revision
  or v_bill.status not in ('issued','approved') or v_bill.total_amount is null
  or round(v_bill.total_amount*100)::bigint<>v_order.amount_paise
  or round(v_booking.amount_paid*100)::bigint<>v_order.amount_paise then
  raise exception 'PAID_AMOUNT_DOES_NOT_MATCH_FINAL_BILL_SNAPSHOT' using errcode='55000';
 end if;
 v_amount:=round(v_booking.amount_paid,2);
 if round(v_request.amount,2)<>v_amount then raise exception 'REFUND_AMOUNT_MUST_EQUAL_FULL_PAID_BOOKING_AMOUNT' using errcode='55000'; end if;
 if exists(select 1 from public.srk_worker_payout_earning_allocations a
  join public.srk_worker_payout_requests p on p.id=a.payout_request_id
  where a.booking_id=v_booking.id and p.status='paid')
 or exists(select 1 from public.srk_worker_earnings e
  join public.srk_worker_payout_requests p on p.worker_id=e.worker_id and p.status='paid'
  where e.booking_id=v_booking.id and not exists(select 1 from public.srk_worker_payout_earning_allocations a where a.payout_request_id=p.id))
 then raise exception 'BOOKING_WORKER_PAYOUT_ALREADY_PAID_RECONCILIATION_REQUIRED'; end if;
 select * into v_refund from public.srk_razorpay_refunds rr where rr.booking_id=v_booking.id for update;
 if found then
  if v_refund.status='failed' then raise exception 'PREVIOUS_REFUND_FAILED_RECONCILE_FIRST'; end if;
  if v_refund.payment_id is distinct from v_booking.razorpay_payment_id or v_refund.amount_paise<>round(v_amount*100)::bigint then
   raise exception 'EXISTING_REFUND_DOES_NOT_MATCH_PAID_FINAL_BILL';
  end if;
  update public.srk_booking_refund_requests
  set status=case when v_refund.status='processed' then 'processed' else 'processing' end,
   refund_record_id=v_refund.id,updated_at=clock_timestamp(),
   processed_at=case when v_refund.status='processed' then coalesce(v_refund.processed_at,clock_timestamp()) else null end
  where id=v_request.id;
  return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
  return;
 end if;
 select * into v_payout from public.srk_electrician_payouts where booking_id=v_booking.id for update;
 if found then
  v_has_legacy_payout:=true;
  if v_payout.payout_status='paid' then raise exception 'LEGACY_WORKER_PAYOUT_ALREADY_PAID_RECONCILIATION_REQUIRED'; end if;
  if v_payout.payout_status not in ('pending','blocked') then raise exception 'LEGACY_WORKER_PAYOUT_STATE_REQUIRES_RECONCILIATION'; end if;
  update public.srk_electrician_payouts set payout_status='blocked',payout_note='Customer refund in progress',updated_at=clock_timestamp() where id=v_payout.id;
 end if;
 insert into public.srk_razorpay_refunds
  (booking_id,payment_id,amount,amount_paise,idempotency_key,status,reason,admin_user_id,previous_payout_note)
 values(v_booking.id,v_booking.razorpay_payment_id,v_amount,round(v_amount*100)::bigint,
  replace(gen_random_uuid()::text,'-',''),'requested',left('Customer refund request: '||v_request.reason,250),auth.uid(),
  case when v_has_legacy_payout then v_payout.payout_note else null end)
 returning * into v_refund;
 update public.srk_booking_refund_requests
 set status='processing',refund_record_id=v_refund.id,decided_by=auth.uid(),updated_at=clock_timestamp()
 where id=v_request.id;
 return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_session_action(
 p_session_id uuid,p_action text,p_pause_reason text DEFAULT NULL,
 p_note text DEFAULT NULL,p_idempotency_key text DEFAULT NULL
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_assignment public.srk_booking_workers%rowtype;
 v_existing_event public.srk_worker_session_events%rowtype;
 v_user_id uuid; v_booking_worker_id uuid; v_booking_id uuid;
 v_now timestamptz:=clock_timestamp(); v_elapsed bigint;
 v_booking public.service_bookings%rowtype; v_expected_event_type text;
 v_auto_resume_distance numeric; v_distance_m numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_idempotency_key is not null and
  (length(btrim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then
  raise exception 'Invalid idempotency key' using errcode='22023';
 end if;
 select booking_worker_id into v_booking_worker_id from public.srk_worker_work_sessions where id=p_session_id;
 if not found then raise exception 'Work session not found'; end if;
 select booking_id into v_booking_id from public.srk_booking_workers where id=v_booking_worker_id;
 if not found then raise exception 'Booking assignment not found'; end if;
 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 select * into v_assignment from public.srk_booking_workers where id=v_booking_worker_id for update;
 if not found then raise exception 'Booking assignment not found'; end if;
 select * into v_session from public.srk_worker_work_sessions
 where id=p_session_id and booking_worker_id=v_assignment.id for update;
 if not found then raise exception 'Work session not found'; end if;
 select user_id into v_user_id from public.srk_worker_profiles where id=v_assignment.worker_id;
 if v_user_id is distinct from auth.uid() and not coalesce(public.is_srk_admin(),false) then
  raise exception 'Not authorized for this work session';
 end if;
 if p_idempotency_key is not null then
  v_expected_event_type:=case p_action when 'start' then 'started' when 'pause' then 'paused'
   when 'resume' then 'resumed' when 'complete' then 'completed' else null end;
  select * into v_existing_event from public.srk_worker_session_events
  where idempotency_key=p_idempotency_key for share;
  if found then
   if v_existing_event.session_id is distinct from p_session_id
    or v_existing_event.event_type is distinct from v_expected_event_type
    or v_existing_event.actor_user_id is distinct from auth.uid()
    or v_existing_event.pause_reason is distinct from p_pause_reason
    or v_existing_event.note is distinct from p_note
    or v_existing_event.source is distinct from 'app' then
    raise exception 'Idempotency key was already used for a different timer event' using errcode='22023';
   end if;
   return v_session;
  end if;
 end if;
 if p_action='start' then
  if v_session.session_status<>'not_started' then raise exception 'Session cannot be started from current state'; end if;
  if v_session.start_latitude is null or v_session.start_longitude is null
   or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
   or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
   raise exception 'A fresh GPS location is required before starting the work timer';
  end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=v_now,last_resumed_at=v_now,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_assignment.id and assignment_status in ('accepted','assigned','paused');
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
  where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'started',v_now,auth.uid(),p_note,p_idempotency_key);
 elsif p_action='pause' then
  if v_session.session_status<>'running' then raise exception 'Only a running session can be paused'; end if;
  if p_pause_reason is null or p_pause_reason not in ('lunch','market_other') then
   raise exception 'Pause reason must be Lunch or Market/Other Task';
  end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions set session_status='paused',pause_started_at=v_now,
   pause_minimum_until=v_now+make_interval(mins=>case when p_pause_reason='lunch'
    then coalesce((v_booking.operational_settings_snapshot->>'lunch_pause_minimum_minutes')::integer,60)
    else coalesce((v_booking.operational_settings_snapshot->>'other_pause_minimum_minutes')::integer,120) end),
   billable_seconds=least(5184000,billable_seconds+v_elapsed),last_resumed_at=null,
   pause_reason=p_pause_reason,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now where id=v_assignment.id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,idempotency_key)
  values(p_session_id,'paused',v_now,auth.uid(),p_pause_reason,p_note,p_idempotency_key);
 elsif p_action='resume' then
  if v_session.session_status<>'paused' then raise exception 'Only a paused session can be resumed'; end if;
  if v_session.pause_minimum_until is not null and v_now<v_session.pause_minimum_until then
   raise exception 'Minimum pause duration has not elapsed';
  end if;
  if v_session.pause_reason in ('gps_outside_worksite','lunch','market_other','admin_override') then
   if v_session.start_latitude is null or v_session.start_longitude is null
    or v_session.last_gps_latitude is null or v_session.last_gps_longitude is null
    or v_session.last_gps_at is null or v_session.last_gps_at<v_now-interval '2 minutes' then
    raise exception 'Fresh GPS location is required to resume inside the work-site radius';
   end if;
   v_auto_resume_distance:=coalesce(
    (v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
    (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);
   v_distance_m:=6371000*2*asin(sqrt(
    power(sin(radians(v_session.last_gps_latitude-v_session.start_latitude)/2),2)
    +cos(radians(v_session.start_latitude))*cos(radians(v_session.last_gps_latitude))
    *power(sin(radians(v_session.last_gps_longitude-v_session.start_longitude)/2),2)
   ));
   if v_distance_m>v_auto_resume_distance then raise exception 'Cannot resume while outside the configured work-site radius'; end if;
  end if;
  update public.srk_worker_work_sessions set session_status='running',last_resumed_at=v_now,pause_reason=null,
   pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now where id=v_assignment.id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'resumed',v_now,auth.uid(),p_note,p_idempotency_key);
 elsif p_action='complete' then
  if v_session.session_status not in ('running','paused') then raise exception 'Session cannot be completed from current state'; end if;
  v_elapsed:=case when v_session.session_status='running'
   then greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint) else 0 end;
  update public.srk_worker_work_sessions set session_status='completed',
   billable_seconds=least(5184000,billable_seconds+v_elapsed),ended_at=v_now,last_resumed_at=null,
   completion_note=p_note,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='assigned',updated_at=v_now
  where id=v_assignment.id and assignment_status in ('working','paused');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
  values(p_session_id,'completed',v_now,auth.uid(),p_note,p_idempotency_key);
 else
  raise exception 'Unsupported session action';
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_submit_worker_document(
 p_document_type text,p_storage_path text,p_file_name text,p_mime_type text,
 p_file_size_bytes bigint,p_application_id uuid DEFAULT NULL
) RETURNS public.srk_worker_documents
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare v_worker uuid; v_doc public.srk_worker_documents%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select id into v_worker from public.srk_worker_profiles where user_id=auth.uid();
 if p_application_id is not null and not exists(
  select 1 from public.srk_worker_applications where id=p_application_id and user_id=auth.uid()
 ) then raise exception 'Application does not belong to you'; end if;
 if v_worker is null and p_application_id is null then raise exception 'Worker application or profile required'; end if;
 if p_storage_path is null or p_storage_path like '/%' or p_storage_path like '%..%'
  or split_part(p_storage_path,'/',1)<>auth.uid()::text
  or p_storage_path ~ '[\\\\]' then
  raise exception 'Document path must be inside your private folder';
 end if;
 if p_document_type not in ('photo','identity_proof','address_proof','experience_certificate','trade_certificate','bank_proof','other') then
  raise exception 'Unsupported document type';
 end if;
 if p_file_name is null or length(btrim(p_file_name)) not between 1 and 255
  or p_file_name ~ '[/\\\\]' then
  raise exception 'A valid file name is required';
 end if;
 if lower(coalesce(p_mime_type,'')) not in ('image/jpeg','image/png','application/pdf') then
  raise exception 'Only JPEG, PNG or PDF documents are accepted';
 end if;
 if p_file_size_bytes is null or p_file_size_bytes not between 1 and 20971520 then
  raise exception 'Document must be between 1 byte and 20 MB';
 end if;
 insert into public.srk_worker_documents(
  worker_id,application_id,document_type,storage_path,file_name,mime_type,file_size_bytes
 ) values(v_worker,p_application_id,p_document_type,p_storage_path,btrim(p_file_name),
  lower(p_mime_type),p_file_size_bytes)
 returning * into v_doc;
 return v_doc;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_version_service_pricing_rule(
 p_pricing_rule_id uuid,p_pricing_unit text,p_technician_rate numeric,p_helper_rate numeric,
 p_base_hp numeric,p_base_hp_price numeric,p_hp_step_amount numeric,p_timer_enabled boolean,
 p_materials_charged_separately boolean,p_winding_charged_separately boolean,
 p_pricing_note text,p_hp_tiers jsonb,p_change_reason text
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_old public.srk_service_pricing_rules%rowtype;
 v_new_id uuid;
 v_now timestamptz:=clock_timestamp();
 v_tier_count integer:=0;
 v_bad_count integer:=0;
 v_category_code text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not public.srk_has_admin_permission('catalog.manage') then raise exception 'Permission denied: catalog.manage required'; end if;
 if p_pricing_rule_id is null then raise exception 'Pricing rule ID is required'; end if;
 if p_pricing_unit not in ('hour','per_item','motor_hp') then raise exception 'Invalid pricing unit'; end if;
 if p_timer_enabled is null or p_materials_charged_separately is null or p_winding_charged_separately is null then
  raise exception 'Pricing flags are required';
 end if;
 if p_materials_charged_separately is true then raise exception 'Material billing is disabled by the approved SRK ELECTRONIC policy'; end if;
 if p_winding_charged_separately is true then raise exception 'Motor Winding is outside SRK ELECTRONIC; winding charges cannot be enabled'; end if;
 if p_helper_rate is not null and p_helper_rate<0 then raise exception 'Helper rate cannot be negative'; end if;
 if p_change_reason is null or length(btrim(p_change_reason))<10 then raise exception 'Change reason must contain at least 10 non-space characters'; end if;
 if p_hp_tiers is null or jsonb_typeof(p_hp_tiers)<>'array' then raise exception 'HP tiers must be supplied as a JSON array (use [] when not applicable)'; end if;

 perform pg_advisory_xact_lock(hashtextextended(p_pricing_rule_id::text,0));
 select * into v_old from public.srk_service_pricing_rules where id=p_pricing_rule_id for update;
 if not found then raise exception 'Pricing rule not found'; end if;
 if v_old.effective_to is not null then raise exception 'Only the current pricing rule version can be changed'; end if;
 if v_now<=v_old.effective_from then raise exception 'Pricing rule effective time conflict'; end if;
 select c.category_code into v_category_code from public.srk_service_categories c
 where c.id=v_old.category_id and c.is_active;
 if not found or not exists(select 1 from public.srk_service_types s
  where s.id=v_old.service_type_id and s.category_id=v_old.category_id and s.is_active) then
  raise exception 'Only active catalog items can receive a new pricing version';
 end if;
 if (v_category_code='motor_pump_technician' and p_pricing_unit<>'motor_hp')
  or (v_category_code='cooler_technician' and p_pricing_unit<>'per_item')
  or (v_category_code not in ('motor_pump_technician','cooler_technician') and p_pricing_unit<>'hour') then
  raise exception 'Pricing unit does not match the approved service category pricing model';
 end if;

 if p_pricing_unit='hour' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not true
   or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
   or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Hourly pricing requires positive technician rate, timer enabled, and no HP fields/tiers';
  end if;
 elsif p_pricing_unit='per_item' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not false
   or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
   or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Per-item pricing requires positive item rate, timer disabled, and no HP fields/tiers';
  end if;
 else
  if p_timer_enabled is not false or p_base_hp is null or p_base_hp<0.5
   or p_base_hp_price is null or p_base_hp_price<=0 or p_hp_step_amount is null or p_hp_step_amount<=0
   or p_technician_rate is not null or p_helper_rate is not null
   or jsonb_array_length(p_hp_tiers)=0 then
   raise exception 'Motor HP pricing requires timer disabled, positive HP base values and HP tiers';
  end if;
  if exists(select 1 from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric)
   where x.motor_hp is null or x.motor_hp<0.5 or x.fixed_price is null or x.fixed_price<=0) then
   raise exception 'Every HP tier requires motor_hp >= 0.5 and positive fixed_price';
  end if;
  select count(*) into v_tier_count from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
  select count(*) into v_bad_count from (
   select x.motor_hp from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric)
   group by x.motor_hp having count(*)>1
  ) d;
  if v_tier_count=0 or v_bad_count>0 then raise exception 'HP tiers must be non-empty and have unique HP values'; end if;
 end if;

 update public.srk_service_pricing_rules set effective_to=v_now
 where id=v_old.id and effective_to is null;
 insert into public.srk_service_pricing_rules(
  category_id,service_type_id,pricing_unit,technician_rate,helper_rate,
  base_hp,base_hp_price,hp_step_amount,timer_enabled,
  materials_charged_separately,winding_charged_separately,pricing_note,
  effective_from,effective_to,created_by,change_reason
 ) values(
  v_old.category_id,v_old.service_type_id,p_pricing_unit,p_technician_rate,p_helper_rate,
  p_base_hp,p_base_hp_price,p_hp_step_amount,p_timer_enabled,
  false,false,nullif(btrim(p_pricing_note),''),
  v_now,null,auth.uid(),btrim(p_change_reason)
 ) returning id into v_new_id;
 if p_pricing_unit='motor_hp' then
  insert into public.srk_service_pricing_hp_tiers(pricing_rule_id,motor_hp,fixed_price,created_by)
  select v_new_id,x.motor_hp,x.fixed_price,auth.uid()
  from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
 end if;
 return v_new_id;
end
